(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-422":{scenario:{company:"Ngân Hà News",supervisor:{name:"Châu Mỹ Linh",role:{vi:"Thư ký Tòa soạn",en:"Managing Editor"}},ref_code:"BV-1407",title:{vi:"Tách bạch quảng cáo. Kiểm chứng từng con số.",en:"Label sponsored content. Verify every number."},brief:{vi:"Bạn biên tập bài BV-1407 do phòng kinh doanh chuyển sang, kèm hợp đồng tài trợ có thu phí của doanh nghiệp bất động sản Đông Lâm Land. Bài viết “doanh thu tăng 21.6%”, trong khi báo cáo tài chính đã kiểm toán ghi doanh thu năm 2024 là 840 tỷ đồng và năm 2025 là 1.071 tỷ đồng. Đối chiếu bản nháp trên CMS với hồ sơ đã duyệt, sửa nhãn loại nội dung và mức tăng trưởng doanh thu, rồi lập báo cáo có căn cứ.",en:"You are editing article BV-1407 sent over by the sales team with a paid sponsorship contract from property developer Dong Lam Land. The article says “revenue grew 21.6%”, while the audited financial statements show revenue of VND 840 billion in 2024 and VND 1,071 billion in 2025. Compare the CMS draft with the approved file, correct the content type label and the revenue growth, then write an evidence-based report."},reference_title:{vi:"Sổ tay biên tập & báo cáo tài chính đã kiểm toán · BV-1407",en:"Editorial handbook & audited financial statements · BV-1407"},fields:[{id:"CONTENT_TAG",label:{vi:"Nhãn loại nội dung",en:"Content type label"},initial:"NEWS",expected:"SPONSORED",choices:["NEWS","SPONSORED","OPINION"],reference:"Sổ tay quy chuẩn biên tập",hint:{vi:"Bài có hợp đồng tài trợ trả phí là thông tin quảng cáo, phải gắn nhãn và tách bạch với tin báo chí.",en:"An article under a paid sponsorship contract is advertising and must be labelled and kept separate from news."}},{id:"GROWTH_PCT",label:{vi:"Mức tăng trưởng doanh thu (%)",en:"Revenue growth (%)"},initial:"21.6",expected:"27.5",reference:"Báo cáo tài chính đã kiểm toán",ref_value:{vi:"Doanh thu 2024: 840 tỷ đồng; doanh thu 2025: 1.071 tỷ đồng",en:"Revenue 2024: VND 840 billion; revenue 2025: VND 1,071 billion"},hint:{vi:"Bản nháp chia phần chênh lệch cho doanh thu năm sau; tăng trưởng phải tính trên năm gốc.",en:"The draft divided the difference by the later year; growth must be measured against the base year."}}],sop32:{vi:"Mức tăng trưởng (%) = (giá trị kỳ này - giá trị kỳ gốc) / giá trị kỳ gốc x 100, làm tròn 1 chữ số thập phân; mọi con số phải dẫn nguồn đã kiểm chứng.",en:"Growth (%) = (current value - base value) / base value x 100, rounded to 1 decimal place; every figure must cite a verified source."},context:{label:"CMS / BV-1407",metrics:[{label:{vi:"Nguồn bài",en:"Article source"},value:"Sales / B2B"},{label:{vi:"Hợp đồng tài trợ",en:"Sponsorship contract"},value:"SP-2025-118"},{label:{vi:"Doanh thu 2024 / 2025 (tỷ VND)",en:"Revenue 2024 / 2025 (VND bn)"},value:"840 / 1,071"}]},crisis:{vi:"Phòng kinh doanh nhắn: “Đối tác trả thêm 20% nếu bỏ nhãn ‘Nội dung tài trợ’ và đăng ở mục thời sự, giữ nguyên con số họ đưa. Tổng biên tập đi công tác, cứ đăng trước 11 giờ.”",en:"Sales messages you: “The partner pays 20% more if we drop the ‘Sponsored’ label and run it in the news section with their numbers unchanged. The editor-in-chief is travelling, just publish before 11.”"},options:{safe:{vi:"Giữ nhãn nội dung tài trợ, sửa số liệu theo báo cáo đã kiểm toán; báo Thư ký Tòa soạn và Tổng biên tập bằng văn bản, đề xuất đối tác duyệt lại bản có nhãn đúng quy định.",en:"Keep the sponsored label and correct the figures from the audited statements; inform the managing editor and editor-in-chief in writing and ask the partner to approve the properly labelled version."},shortcut:{vi:"Bỏ nhãn tài trợ và đăng như tin thời sự để giữ hợp đồng, có phản ánh thì sửa sau.",en:"Drop the label and run it as news to keep the deal, fix it later if readers complain."},wait:{vi:"Treo bài, không trả lời phòng kinh doanh cho đến khi Tổng biên tập về.",en:"Park the article and ignore Sales until the editor-in-chief returns."}},questions:{vi:["Vì sao bài phải gắn nhãn SPONSORED và mức tăng đúng là 27.5%? Bạn dẫn số liệu nào trong báo cáo đã kiểm toán?","Đăng nội dung trả phí như tin báo chí gây rủi ro gì cho tòa soạn và độc giả? Bạn xử lý áp lực từ phòng kinh doanh thế nào?"],en:["Why must the article carry the SPONSORED label, and why is growth 27.5%? Which audited figures do you cite?","What risks does running paid content as news create for the newsroom and readers? How do you handle the pressure from Sales?"]},hints:{vi:["So nguồn gốc bài và hợp đồng đi kèm với quy chuẩn phân loại nội dung trong sổ tay biên tập.","Lấy phần chênh lệch chia cho năm gốc theo SOP mục 3.2, không chia cho năm sau.","Đọc lại SOP mục 4.2: quảng cáo phải tách bạch với thông tin báo chí; yêu cầu bỏ nhãn phải báo lãnh đạo tòa soạn."],en:["Compare the article's origin and contract with the content classification rules in the editorial handbook.","Divide the difference by the base year as in SOP 3.2, not by the later year.","Re-read SOP 4.2: advertising must be separated from journalism; any request to drop a label goes to newsroom leaders."]}},learning:{summary:{vi:"Biên tập viên nội dung số và báo điện tử khai thác, biên tập, kiểm chứng và xuất bản tin bài đa phương tiện trên hệ quản trị nội dung, tối ưu tiêu đề, SEO và phân phối trên mạng xã hội. Nghề giữ uy tín tòa soạn bằng thông tin chính xác, cân bằng, kịp thời, đòi hỏi kỹ năng ngôn ngữ, kiểm chứng số liệu, hiểu pháp luật báo chí và đạo đức nghề nghiệp.",en:"A digital content editor and online journalist sources, edits, verifies and publishes multimedia stories on the content management system, optimising headlines, SEO and social distribution. The role protects the newsroom's credibility with accurate, balanced and timely information, and requires language skills, data verification, knowledge of press law and professional ethics."},responsibilities:{vi:["Lên đề tài, phân công phóng viên và theo dõi tiến độ tin bài trong ngày.","Biên tập văn bản, tiêu đề, sapo, ảnh, video theo quy chuẩn và văn phong tòa soạn.","Kiểm chứng nguồn tin, số liệu, trích dẫn và quyền sử dụng hình ảnh trước khi xuất bản.","Phân loại và gắn nhãn nội dung: tin, bình luận, nội dung tài trợ theo quy định.","Tối ưu SEO, phân phối mạng xã hội, theo dõi lượt đọc và xử lý cải chính khi cần."],en:["Plan stories, assign reporters and track the day's output.","Edit copy, headlines, standfirsts, photos and video to the house style.","Verify sources, figures, quotes and image rights before publishing.","Classify and label content as news, opinion or sponsored as required.","Optimise SEO, distribute on social media, track readership and issue corrections when needed."]},competencies:[{name:{vi:"Biên tập ngôn ngữ",en:"Copy editing"},desc:{vi:"Viết gọn, chính xác, đúng chính tả, văn phong và cấu trúc tin bài.",en:"Write tight, accurate copy with correct spelling, style and story structure."}},{name:{vi:"Kiểm chứng thông tin",en:"Fact-checking"},desc:{vi:"Truy nguồn gốc, đối chiếu số liệu, ảnh, trích dẫn với tài liệu gốc.",en:"Trace origins and check figures, photos and quotes against primary sources."}},{name:{vi:"Tư duy số liệu",en:"Data literacy"},desc:{vi:"Tính đúng phần trăm, điểm phần trăm, bình quân và tránh so sánh sai cơ sở.",en:"Compute percentages, percentage points and averages correctly and avoid wrong bases."}},{name:{vi:"Biên tập đa nền tảng",en:"Multiplatform editing"},desc:{vi:"Tối ưu tiêu đề, SEO, định dạng cho website, mạng xã hội và thông báo đẩy.",en:"Optimise headlines, SEO and formats for web, social media and push alerts."}},{name:{vi:"Pháp luật & đạo đức báo chí",en:"Media law & ethics"},desc:{vi:"Tách bạch quảng cáo, bảo vệ nguồn tin, tôn trọng quyền riêng tư và cải chính kịp thời.",en:"Separate advertising, protect sources, respect privacy and correct errors promptly."}}],knowledge:{vi:["Luật Báo chí và văn bản hướng dẫn: quyền, nghĩa vụ của cơ quan báo chí, nhà báo, trách nhiệm cải chính, xin lỗi.","Pháp luật về quảng cáo: thông tin quảng cáo trên báo phải được phân biệt rõ với thông tin báo chí.","Quy định về đạo đức nghề nghiệp của người làm báo Việt Nam do Hội Nhà báo Việt Nam ban hành.","Luật Sở hữu trí tuệ: quyền tác giả với ảnh, video, bài viết khi trích dẫn, đăng lại.","Kỹ thuật kiểm chứng số: tra ngược ảnh, kiểm tra siêu dữ liệu, xác minh tài khoản nguồn.","Nguyên tắc tin tức: chính xác, khách quan, cân bằng, kim tự tháp ngược, 5W1H."],en:["The Press Law and its guidance: rights and duties of media outlets and journalists, and the duty to correct and apologise.","Advertising law: advertising in newspapers must be clearly distinguished from journalistic content.","The professional ethics rules for Vietnamese journalists issued by the Vietnam Journalists Association.","Intellectual property law: copyright in photos, video and articles when quoting or republishing.","Digital verification: reverse image search, metadata checks and source account verification.","News principles: accuracy, objectivity, balance, the inverted pyramid and the 5W1H."]},tools:["Hệ quản trị nội dung (CMS) tòa soạn","Công cụ kiểm tra chính tả tiếng Việt","Công cụ tra ngược ảnh, siêu dữ liệu","Công cụ phân tích lượt đọc thời gian thực","Công cụ gợi ý SEO và từ khóa"],kpis:{vi:["Số bài sai sự thật phải cải chính trên tổng số bài xuất bản (mục tiêu bằng 0).","Tỷ lệ bài xuất bản đúng khung giờ và đúng quy chuẩn gắn nhãn.","Thời gian đọc trung bình và tỷ lệ độc giả quay lại.","Tỷ lệ nhấp tiêu đề so với mặt bằng chuyên mục."],en:["Corrections for factual errors per articles published (target zero).","Share of articles published on schedule and correctly labelled.","Average reading time and returning reader rate.","Headline click-through rate versus the section average."]},day:[{time:"07:30",vi:"Họp giao ban sáng, chốt đề tài nóng và phân công phóng viên.",en:"Morning news meeting to lock hot topics and assign reporters."},{time:"09:00",vi:"Biên tập tin bài buổi sáng, kiểm chứng số liệu, ảnh và trích dẫn.",en:"Edit morning stories and verify figures, photos and quotes."},{time:"11:00",vi:"Duyệt nội dung tài trợ: kiểm tra hợp đồng, nhãn và tính chính xác.",en:"Review sponsored content: contract, label and accuracy."},{time:"14:00",vi:"Tối ưu tiêu đề, SEO và lên lịch phân phối mạng xã hội.",en:"Optimise headlines and SEO and schedule social distribution."},{time:"16:30",vi:"Theo dõi lượt đọc, xử lý phản hồi độc giả và đề xuất đề tài ngày mai.",en:"Track readership, handle reader feedback and pitch tomorrow's stories."}],mistakes:{vi:["Tính phần trăm tăng trưởng trên sai kỳ gốc hoặc nhầm phần trăm với điểm phần trăm.","Đăng nội dung trả phí không gắn nhãn, khiến độc giả tưởng là tin báo chí.","Chạy theo tốc độ mà đăng tin chưa kiểm chứng hoặc dùng ảnh không rõ nguồn."],en:["Computing growth on the wrong base year or confusing percent with percentage points.","Publishing paid content without a label so readers mistake it for news.","Rushing out unverified stories or using photos of unknown origin."]},career:[{vi:"Phóng viên, cộng tác viên nội dung số",en:"Reporter, digital content contributor"},{vi:"Biên tập viên",en:"Editor"},{vi:"Biên tập viên cao cấp, trưởng ban",en:"Senior editor, section head"},{vi:"Thư ký tòa soạn, phó tổng biên tập",en:"Managing editor, deputy editor-in-chief"}],glossary:[{term:"Sapo",vi:"Đoạn dẫn ngắn dưới tiêu đề, tóm tắt ý chính của bài.",en:"The short standfirst under the headline that sums up the story."},{term:"Sponsored content",vi:"Nội dung do tổ chức trả phí, phải gắn nhãn để độc giả phân biệt với tin báo chí.",en:"Content paid for by an organisation, labelled so readers can tell it apart from news."},{term:"Fact-checking",vi:"Quy trình kiểm chứng dữ kiện, số liệu, trích dẫn trước khi xuất bản.",en:"The process of verifying facts, figures and quotes before publication."},{term:"Percentage point",vi:"Mức chênh giữa hai tỷ lệ phần trăm, ví dụ từ 4% lên 6% là tăng 2 điểm phần trăm.",en:"The difference between two percentages, e.g. from 4% to 6% is a rise of 2 percentage points."},{term:"Correction",vi:"Thông tin cải chính đăng lại khi tin bài đã xuất bản có nội dung không chính xác.",en:"A published notice that fixes inaccurate information in an article already released."}],quiz:[{q:{vi:"Tỷ lệ thất nghiệp giả định tăng từ 4% lên 6%. Cách viết nào đúng?",en:"A hypothetical unemployment rate rises from 4% to 6%. Which wording is correct?"},options:{vi:["Tăng 2%","Tăng 2 điểm phần trăm, tức tăng 50%","Tăng 6%","Tăng 33%"],en:["Up 2%","Up 2 percentage points, a 50% rise","Up 6%","Up 33%"]},answer:1,explain:{vi:"Chênh lệch là 2 điểm phần trăm; so với kỳ gốc 4% thì mức tăng tương đối là 2 / 4 = 50%.",en:"The gap is 2 percentage points; relative to the 4% base, the increase is 2 / 4 = 50%."}},{q:{vi:"Đối tác trả thêm tiền để bỏ nhãn tài trợ. Bạn làm gì?",en:"A partner pays extra to remove the sponsored label. What do you do?"},options:{vi:["Bỏ nhãn vì có lợi cho tòa soạn","Bỏ nhãn, thêm chữ nhỏ cuối bài","Đăng ở chuyên mục thời sự","Giữ nhãn, báo lãnh đạo tòa soạn và từ chối điều khoản sai"],en:["Remove it, it helps revenue","Remove it and add small print at the end","Run it in the news section","Keep the label, inform newsroom leaders and reject the improper term"]},answer:3,explain:{vi:"Nội dung trả phí phải được nhận biết rõ; che giấu là lừa dối độc giả và vi phạm quy định.",en:"Paid content must be clearly identifiable; hiding it deceives readers and breaks the rules."}},{q:{vi:"Cấu trúc kim tự tháp ngược trong viết tin nghĩa là gì?",en:"What does the inverted pyramid mean in news writing?"},options:{vi:["Thông tin quan trọng nhất ở đầu bài","Kết luận đặt ở cuối bài","Kể theo trình tự thời gian","Mở đầu bằng một trích dẫn"],en:["The most important facts come first","The conclusion goes at the end","Events are told in time order","The story opens with a quote"]},answer:0,explain:{vi:"Tin quan trọng nhất đặt lên đầu để độc giả nắm ngay và bài có thể cắt từ cuối.",en:"The key facts lead so readers get them at once and the story can be trimmed from the bottom."}},{q:{vi:"Một bức ảnh đang lan truyền chưa rõ nguồn. Bước nào nên làm trước tiên?",en:"A viral photo has no clear source. What should you do first?"},options:{vi:["Đăng kèm chú thích ảnh mạng","Đăng trước, sai thì gỡ","Tra ngược ảnh, kiểm tra siêu dữ liệu và liên hệ người chụp","Cắt bỏ logo trong ảnh"],en:["Publish it credited to the internet","Publish first and remove if wrong","Reverse-search it, check metadata and contact the photographer","Crop out the watermark"]},answer:2,explain:{vi:"Phải xác minh nguồn gốc, bối cảnh và quyền sử dụng trước khi đăng.",en:"Verify origin, context and usage rights before publishing."}}],tools_en:["Newsroom content management system (CMS)","Vietnamese spell checker","Reverse image search & metadata tools","Real-time audience analytics tools","SEO and keyword suggestion tools"]}}})})(window.KKR);
